import pathlib
p = pathlib.Path('/private/tmp/claude-501/-Users-guillaumeloulier-PhpstormProjects-oss-elephc--claude-worktrees-streams-csv-signature/c8dbe38f-1f79-484f-9b83-62bacab9ca56/scratchpad/uv/add_glob_flags.py')
t = p.read_text()
start = t.index("new = '''    ensure_arg_count_between(inst, \"glob\", 1, 2)?;")
end = t.index("assert t.count(old) == 1, 'glob lowering not found'")
new_block = '''new = \'\'\'    ensure_arg_count_between(inst, "glob", 1, 2)?;
    let path = expect_operand(inst, 0)?;
    load_string_to_result(ctx, path, "glob")?;
    // `$flags` rides beside the pattern pair, the way `scandir`'s `$sorting_order` does. php's own
    // `GLOB_ONLYDIR` is not a libc flag on any target the oracle records — it is php's `1 << 30`
    // fallback — so the runtime masks it off before the libc call and filters afterwards.
    match inst.operands.get(1).copied() {
        None => match ctx.emitter.target.arch {
            Arch::AArch64 => ctx.emitter.instruction("mov x3, #0"),             // php's default is no flags
            Arch::X86_64 => ctx.emitter.instruction("xor ecx, ecx"),
        },
        Some(flags) => {
            match ctx.emitter.target.arch {
                Arch::AArch64 => abi::emit_push_reg_pair(ctx.emitter, "x1", "x2"),
                Arch::X86_64 => abi::emit_push_reg_pair(ctx.emitter, "rax", "rdx"),
            }
            require_int(ctx.load_value_to_result(flags)?.codegen_repr(), "glob flags")?;
            match ctx.emitter.target.arch {
                Arch::AArch64 => {
                    ctx.emitter.instruction("mov x9, x0");                      // hold the flags while the pair returns
                    abi::emit_pop_reg_pair(ctx.emitter, "x1", "x2");
                    ctx.emitter.instruction("mov x3, x9");
                }
                Arch::X86_64 => {
                    ctx.emitter.instruction("mov rcx, rax");
                    abi::emit_pop_reg_pair(ctx.emitter, "rax", "rdx");
                }
            }
        }
    }
    abi::emit_call_label(ctx.emitter, "__rt_glob");\'\'\'
'''
p.write_text(t[:start] + new_block + t[end:])
print('lowering patch aligned with the repo idiom')
